mapper.select:
SELECT l.id, l.order_no, l.user_id, l.spot_id, s.name AS spot_name,
       l.operator_id, l.channel, l.checkin_time
FROM checkin_log l
         JOIN spot s ON s.id = l.spot_id


        AND l.spot_id = #{spotId}


        AND l.checkin_time >= #{startDate}


        AND l.checkin_time < #{endDateExclusive}


ORDER BY l.checkin_time DESC, l.id DESC
